abla \kappa &\;\;=\;\;& q(R)\kappa - 
abla^2\mathrm{tr} \, \kappa .
\end{eqnarray}

If $\dim(M) \geq  2$, then we have
\begin{align}\label{eq:zweite_vorstufe_zur_Bianchi_identity}
2 \mathfrak{S}_{123} \nabla_{y_2} \kappa (y_1,y_3) &\;\;=\;\;\left \lbrace \begin{array}{c} 3\nabla^3_{y_1,y_2,y_3}\mathrm{tr} \, \kappa +  6\, \mathrm{d} \, \mathrm{tr} \, \kappa(y_1) \langle y_2,y_3\rangle  + 3\,\mathfrak{S}_{23}\langle y_1,y_2 \rangle\, \mathrm{d} \, \mathrm{tr} \, \kappa(y_3) \end{array} \right \rbrace,\\
