+ R_{x_1,e_i}\kappa(e_2,x_i) + R_{x_1,e_i}\kappa(e_i,x_2)\\ +  R_{x_2,e_i}\kappa(e_i,x_1) + R_{x_2,e_i}\kappa(e_i,x_1)  \end{array} \right \rbrace\\
